let ANTHROPIC_VERSION = '2023-06-01'
let MAX_OUTPUT_TOKENS = 128000

fn required_env(name: String) -> Result[String, String] {
  match env.opt(name) {
    case Some(value) if value.trim.size > 0 -> Result.Ok(value.trim)
    case Some(_) -> Result.Error('The environment variable ${name} is empty')
    case None -> Result.Error('The environment variable ${name} is missing')
  }
}

fn read_stdin -> Result[String, String] {
  let bytes = ByteArray.new

  match Stdin.new.read_all(bytes) {
    case Ok(_) -> Result.Ok(bytes.into_string)
    case Error(error) -> Result.Error('Failed to read stdin: ${error}')
  }
}

fn parse_json_string(text: String, label: String) -> Result[Json, String] {
  match Json.parse(Buffer.new(text)) {
    case Ok(json) -> Result.Ok(json)
    case Error(error) -> Result.Error('Failed to parse the ${label} as JSON: ${error}')
  }
}

fn extract_messages_json(input_json: String) -> Result[String, String] {
  let json = try parse_json_string(input_json, 'stdin input')

  match json {
    case Object(object) -> {
      match object.opt('messages') {
        case Some(value) -> {
          match value {
            case Array(_) -> Result.Ok(value.to_string)
            case _ -> Result.Error('The messages field must be a JSON array')
          }
        }
        case None -> Result.Error('Missing messages field in input payload')
      }
    }
    case Array(array) -> Result.Ok(Json.Array(array).to_string)
    case _ -> Result.Error('Input must be a JSON object with a messages array or a JSON array')
  }
}

fn build_request_body(messages_json: String) -> String {
  '{"model":"${MODEL_ID}","max_tokens":${MAX_OUTPUT_TOKENS},"messages":${messages_json}}'
}

fn text_from_block(block: ref Json) -> String {
  match block {
    case Object(block_map) -> {
      match block_map.opt('type') {
        case Some(String(block_type)) if '${block_type}' == 'text' -> {
          match block_map.opt('text') {
            case Some(String(text)) -> '${text}'
            case _ -> ''
          }
        }
        case _ -> ''
      }
    }
    case _ -> ''
  }
}

fn extract_text_from_response(response_str: String) -> Result[String, String] {
  match parse_json_string(response_str.clone, 'Bedrock response') {
    case Ok(Object(map)) -> {
      match map.opt('content') {
        case Some(Array(content)) -> {
          let result = content
            .iter
            .reduce(StringBuffer.new, fn (buffer, block) {
              let text = text_from_block(block)

              if text.size > 0 {
                buffer.push(text)
              }

              buffer
