let MODEL_ID = 'anthropic.claude-fable-5'
let ANTHROPIC_VERSION = '2023-06-01'
let MAX_OUTPUT_TOKENS = 128000

fn required_env(name: String) -> Result[String, String] {
  match env.opt(name) {
    case Some(value) if value.trim.size > 0 -> Result.Ok(value.trim)
    case Some(_) -> Result.Error('The environment variable ${name} is empty')
    case None -> Result.Error('The environment variable ${name} is missing')
  }
}

fn read_stdin -> Result[String, String] {
  let bytes = ByteArray.new

  match Stdin.new.read_all(bytes) {
    case Ok(_) -> Result.Ok(bytes.into_string)
    case Error(error) -> Result.Error('Failed to read stdin: ${error}')
  }
}

fn parse_json_string(text: String, label: String) -> Result[Json, String] {
  match Json.parse(Buffer.new(text)) {
    case Ok(json) -> Result.Ok(json)
    case Error(error) -> Result.Error('Failed to parse the ${label} as JSON: ${error}')
  }
}

fn extract_messages_json(input_json: String) -> Result[String, String] {
  let json = try parse_json_string(input_json, 'stdin input')

  match json {
    case Object(object) -> {
      match object.opt('messages') {
        case Some(value) -> {
          match value {
            case Array(_) -> Result.Ok(value.to_string)
            case _ -> Result.Error('The messages field must be a JSON array')
          }
        }
        case None -> Result.Error('Missing messages field in input payload')
      }
    }
    case Array(array) -> Result.Ok(Json.Array(array).to_string)
    case _ -> Result.Error('Input must be a JSON object with a messages array or a JSON array')
  }
}

fn build_request_body(messages_json: String) -> String {
  '{"model":"${MODEL_ID}","max_tokens":${MAX_OUTPUT_TOKENS},"messages":${messages_json}}'
}

fn text_from_block(block: ref Json) -> String {
  match block {
    case Object(block_map) -> {
      match block_map.opt('type') {
        case Some(String(block_type)) if '${block_type}' == 'text' -> {
          match block_map.opt('text') {
            case Some(String(text)) -> '${text}'
            case _ -> ''
          }
        }
        case _ -> ''
      }
    }
    case _ -> ''
  }
}

fn extract_text_from_response(response_str: String) -> Result[String, String] {
  match parse_json_string(response_str.clone, 'Bedrock response') {
    case Ok(Object(map)) -> {
      match map.opt('content') {
        case Some(Array(content)) -> {
          let result = content
            .iter
            .reduce(StringBuffer.new, fn (buffer, block) {
              let text = text_from_block(block)

              if text.size > 0 {
                buffer.push(text)
              }

              buffer
            })
            .into_string

          if result.size > 0 {
            Result.Ok(result)
          } else {
            match map.opt('stop_reason') {
              case Some(String(reason)) if '${reason}' == 'refusal' -> {
                Result.Error('Claude Fable 5 refused the request')
              }
              case _ -> Result.Error('No text content block found in Bedrock response')
            }
          }
        }
        case Some(_) -> Result.Error('The content field is not an array in Bedrock response')
        case None -> {
          match map.opt('error') {
            case Some(Object(error_map)) -> {
              match error_map.opt('message') {
                case Some(String(message)) -> Result.Error('Bedrock error: ${message}')
                case _ -> Result.Error('Bedrock returned an error: ${response_str}')
              }
            }
            case Some(String(message)) -> Result.Error('Bedrock error: ${message}')
            case _ -> Result.Error('No content in Bedrock response: ${response_str}')
          }
        }
      }
    }
    case Ok(_) -> Result.Error('Bedrock response is not a JSON object: ${response_str}')
    case Error(error) -> Result.Error('Failed to parse Bedrock response: ${error}')
  }
}

fn invoke_bedrock(api_key: String, body_str: String) -> Result[String, String] {
  let mut command = Command.new('curl')

  command.stdin = Stream.Piped
  command.stdout = Stream.Piped
  command.stderr = Stream.Inherit
  command.arguments = [
    '-sS',
    '-X',
    'POST',
    '-H',
    'x-api-key: ${api_key}',
    '-H',
    'anthropic-version: ${ANTHROPIC_VERSION}',
    '-H',
    'content-type: application/json',
    '-H',
    'accept: application/json',
    '--max-time',
    '600',
    '--connect-timeout',
    '30',
    '--fail-with-body',
    '--data-binary',
    '@-',
    BEDROCK_ENDPOINT,
  ]

  let mut child = match command.spawn {
    case Ok(value) -> value
    case Error(error) -> return Result.Error('Failed to spawn curl: ${error}')
  }

  let stdin = child.stdin := Option.None

  match stdin {
    case Some(mut handle) -> {
      match handle.write_string(body_str) {
        case Ok(_) -> {}
        case Error(error) -> {
          return Result.Error('Failed to write request body to curl: ${error}')
        }
      }

      match handle.close {
        case Ok(_) -> {}
        case Error(error) -> return Result.Error('Failed to close curl stdin: ${error}')
      }
    }
    case None -> return Result.Error('No stdin pipe available for curl')
  }

  let response_bytes = ByteArray.new
  let stdout = child.stdout := Option.None

  match stdout {
    case Some(mut handle) -> {
      match handle.read_all(response_bytes) {
        case Ok(_) -> {}
        case Error(error) -> {
          return Result.Error('Failed to read curl response: ${error}')
        }
      }
    }
    case None -> return Result.Error('No stdout pipe available for curl')
  }

